
'use client';

import { useCallback, useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';

import {
  BookOpen,
  GraduationCap,
  Building2,
  UserRound,
  LogOut,
  RefreshCw,
  FileText,
  Microscope,
  LayoutDashboard,
  AlertCircle,
  ExternalLink,
  CalendarDays,
  BriefcaseBusiness,
} from 'lucide-react';

// ============================================================
// TYPES
// ============================================================

interface FacultyPublication {
  title?: string;
  year?: string | number;
  doi?: string;
  url?: string;
  publication_type?: string;
}

interface FacultyProfile {
  faculty_id?: string;
  name?: string;
  department?: string;
  campus?: string;
  designation?: string;
  photo_url?: string;
  research_areas?: string[];
  publications?: FacultyPublication[];
}

interface DashboardResponse {
  faculty?: FacultyProfile;
  error?: string;
  message?: string;
}

// ============================================================
// CONFIGURATION
// ============================================================

const API_BASE_URL = 'http://localhost:5000';
  

// ============================================================
// HELPERS
// ============================================================

function getInitials(name?: string) {
  if (!name) return 'F';

  return name
    .trim()
    .split(/\s+/)
    .slice(0, 2)
    .map((part) => part[0])
    .join('')
    .toUpperCase();
}

function normalizeResearchAreas(areas?: string[]) {
  if (!Array.isArray(areas)) return [];

  return areas
    .filter((area): area is string => typeof area === 'string')
    .map((area) => area.trim())
    .filter(Boolean);
}

function normalizePublications(
  publications?: FacultyPublication[]
) {
  if (!Array.isArray(publications)) return [];

  return publications.filter(
    (publication) =>
      publication && typeof publication.title === 'string'
  );
}

// ============================================================
// MAIN DASHBOARD
// ============================================================

export default function FacultyDashboardPage() {
  const router = useRouter();

  const [faculty, setFaculty] = useState<FacultyProfile | null>(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [loggingOut, setLoggingOut] = useState(false);
  const [error, setError] = useState('');

  // ==========================================================
  // FETCH FACULTY DASHBOARD DATA
  // ==========================================================

  const fetchDashboard = useCallback(async (isRefresh = false) => {
    if (isRefresh) {
      setRefreshing(true);
    } else {
      setLoading(true);
    }

    setError('');

    try {
      const response = await fetch(
        `${API_BASE_URL}/faculty/dashboard`,
        {
          method: 'GET',
          credentials: 'include',
          headers: {
            'Content-Type': 'application/json',
          },
          cache: 'no-store',
        }
      );

      const result: DashboardResponse = await response.json();

      if (!response.ok) {
        if (response.status === 401 || response.status === 403) {
          throw new Error(
            'Your faculty session is invalid or has expired. Please log in again.'
          );
        }

        throw new Error(
          result.error ||
          result.message ||
          'Unable to load your faculty dashboard.'
        );
      }

      if (!result.faculty) {
        throw new Error(
          'Faculty profile information was not returned by the server.'
        );
      }

      setFaculty(result.faculty);
    } catch (err) {
      setError(
        err instanceof Error
          ? err.message
          : 'Something went wrong while loading the dashboard.'
      );
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, []);

  useEffect(() => {
    fetchDashboard();
  }, [fetchDashboard]);

  // ==========================================================
  // LOGOUT
  // ==========================================================

  const handleLogout = async () => {
    setLoggingOut(true);
    setError('');

    try {
      const response = await fetch(
        `${API_BASE_URL}/faculty/logout`,
        {
          method: 'POST',
          credentials: 'include',
        }
      );

      if (!response.ok) {
        const result = await response.json().catch(() => ({}));

        throw new Error(
          result.error || 'Unable to log out. Please try again.'
        );
      }

      router.replace('/');
    } catch (err) {
      setError(
        err instanceof Error
          ? err.message
          : 'Logout failed. Please try again.'
      );
      setLoggingOut(false);
    }
  };

  // ==========================================================
  // DERIVED DATA
  // ==========================================================

  const researchAreas = normalizeResearchAreas(
    faculty?.research_areas
  );

  const publications = normalizePublications(
    faculty?.publications
  );

  // ==========================================================
  // LOADING STATE
  // ==========================================================

  if (loading) {
    return (
      <main className="flex min-h-screen items-center justify-center bg-slate-50 px-6">
        <div className="text-center">
          <div className="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-indigo-50">
            <RefreshCw className="h-6 w-6 animate-spin text-indigo-600" />
          </div>

          <h2 className="mt-5 text-lg font-semibold text-slate-900">
            Loading your dashboard
          </h2>

          <p className="mt-2 text-sm text-slate-500">
            Retrieving your faculty profile and research information...
          </p>
        </div>
      </main>
    );
  }

  // ==========================================================
  // ERROR STATE
  // ==========================================================

  if (error && !faculty) {
    return (
      <main className="flex min-h-screen items-center justify-center bg-slate-50 px-6">
        <div className="w-full max-w-md rounded-3xl border border-slate-200 bg-white p-8 text-center shadow-sm">
          <div className="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-red-50 text-red-600">
            <AlertCircle className="h-7 w-7" />
          </div>

          <h1 className="mt-5 text-xl font-bold text-slate-900">
            Unable to load dashboard
          </h1>

          <p className="mt-3 text-sm leading-6 text-slate-500">
            {error}
          </p>

          <div className="mt-7 flex flex-col gap-3">
            <button
              type="button"
              onClick={() => fetchDashboard()}
              className="flex h-11 items-center justify-center gap-2 rounded-xl bg-indigo-600 px-5 text-sm font-semibold text-white transition hover:bg-indigo-700"
            >
              <RefreshCw className="h-4 w-4" />
              Try Again
            </button>

            <button
              type="button"
              onClick={() => router.replace('/')}
              className="h-11 rounded-xl border border-slate-200 px-5 text-sm font-semibold text-slate-600 transition hover:bg-slate-50"
            >
              Return to Home
            </button>
          </div>
        </div>
      </main>
    );
  }

  // ==========================================================
  // DASHBOARD
  // ==========================================================

  return (
    <main className="min-h-screen bg-[#f7f8fc] text-slate-900">

      {/* ======================================================
          TOP NAVIGATION
      ====================================================== */}

      <header className="sticky top-0 z-40 border-b border-slate-200 bg-white/90 backdrop-blur-xl">
        <div className="mx-auto flex h-[72px] max-w-7xl items-center justify-between px-5 sm:px-8">

          {/* Logo */}

          <div className="flex items-center gap-3">
            <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-indigo-600 shadow-sm">
              <span className="text-sm font-bold text-white">
                RP
              </span>
            </div>

            <div>
              <p className="text-sm font-bold tracking-tight text-slate-900">
                RESEARCHPILOT
              </p>

              <p className="text-[10px] font-medium uppercase tracking-[0.15em] text-slate-400">
                Faculty Portal
              </p>
            </div>
          </div>

          {/* Right actions */}

          <div className="flex items-center gap-3">
            <div className="hidden items-center gap-2 rounded-xl bg-indigo-50 px-3 py-2 text-xs font-semibold text-indigo-700 sm:flex">
              <BriefcaseBusiness className="h-4 w-4" />
              Faculty Account
            </div>

            <button
              type="button"
              onClick={handleLogout}
              disabled={loggingOut}
              className="flex h-10 items-center gap-2 rounded-xl border border-slate-200 bg-white px-3 text-xs font-semibold text-slate-600 transition hover:border-red-200 hover:bg-red-50 hover:text-red-600 disabled:cursor-not-allowed disabled:opacity-60 sm:px-4"
            >
              {loggingOut ? (
                <RefreshCw className="h-4 w-4 animate-spin" />
              ) : (
                <LogOut className="h-4 w-4" />
              )}

              <span>
                {loggingOut ? 'Logging out...' : 'Log Out'}
              </span>
            </button>
          </div>
        </div>
      </header>

      {/* ======================================================
          MAIN CONTENT
      ====================================================== */}

      <div className="mx-auto max-w-7xl px-5 py-9 sm:px-8 sm:py-12">

        {/* PAGE HEADING */}

        <div className="flex flex-col justify-between gap-5 sm:flex-row sm:items-end">
          <div>
            <div className="mb-3 flex items-center gap-2 text-xs font-semibold uppercase tracking-[0.16em] text-indigo-600">
              <LayoutDashboard className="h-4 w-4" />
              Faculty Dashboard
            </div>

            <h1 className="text-3xl font-bold tracking-tight text-slate-950 sm:text-4xl">
              Welcome back{faculty?.name ? `, ${faculty.name.split(' ')[0]}` : ''}
            </h1>

            <p className="mt-3 max-w-2xl text-sm leading-6 text-slate-500 sm:text-base">
              View your institutional research profile, research areas,
              and associated academic publications.
            </p>
          </div>

          <button
            type="button"
            onClick={() => fetchDashboard(true)}
            disabled={refreshing}
            className="flex h-11 items-center justify-center gap-2 self-start rounded-xl border border-slate-200 bg-white px-4 text-sm font-semibold text-slate-600 shadow-sm transition hover:border-indigo-200 hover:text-indigo-600 disabled:opacity-60 sm:self-auto"
          >
            <RefreshCw
              className={`h-4 w-4 ${refreshing ? 'animate-spin' : ''}`}
            />
            Refresh
          </button>
        </div>

        {/* INLINE ERROR */}

        {error && faculty && (
          <div className="mt-6 flex items-center gap-3 rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-700">
            <AlertCircle className="h-5 w-5 shrink-0" />
            <p>{error}</p>
          </div>
        )}

        {/* ====================================================
            FACULTY PROFILE CARD
        ==================================================== */}

        <section className="mt-9 overflow-hidden rounded-3xl border border-slate-200 bg-white shadow-sm">

          <div className="h-2 bg-gradient-to-r from-indigo-500 via-blue-500 to-violet-500" />

          <div className="flex flex-col gap-6 p-6 sm:flex-row sm:items-center sm:p-8">

            {/* Profile avatar */}

            <div className="flex h-24 w-24 shrink-0 items-center justify-center overflow-hidden rounded-3xl border border-indigo-100 bg-indigo-50 text-3xl font-bold text-indigo-600">
              {faculty?.photo_url ? (
                <img
                  src={faculty.photo_url}
                  alt={faculty.name || 'Faculty profile'}
                  className="h-full w-full object-cover"
                />
              ) : (
                getInitials(faculty?.name)
              )}
            </div>

            {/* Profile information */}

            <div className="min-w-0 flex-1">
              <div className="flex flex-wrap items-center gap-2">
                <h2 className="text-2xl font-bold tracking-tight text-slate-900">
                  {faculty?.name || 'Faculty Member'}
                </h2>

                <span className="rounded-full border border-emerald-100 bg-emerald-50 px-3 py-1 text-[10px] font-bold uppercase tracking-wide text-emerald-700">
                  Faculty
                </span>
              </div>

              <p className="mt-2 text-sm font-medium text-indigo-600">
                {faculty?.designation || 'Faculty Member'}
              </p>

              <div className="mt-4 flex flex-wrap gap-x-5 gap-y-2 text-xs text-slate-500">
                {faculty?.faculty_id && (
                  <div className="flex items-center gap-2">
                    <UserRound className="h-4 w-4 text-slate-400" />
                    Faculty ID: {faculty.faculty_id}
                  </div>
                )}

                {faculty?.department && (
                  <div className="flex items-center gap-2">
                    <Building2 className="h-4 w-4 text-slate-400" />
                    {faculty.department}
                  </div>
                )}

                {faculty?.campus && (
                  <div className="flex items-center gap-2">
                    <GraduationCap className="h-4 w-4 text-slate-400" />
                    {faculty.campus}
                  </div>
                )}
              </div>
            </div>
          </div>
        </section>

        {/* ====================================================
            STATISTICS
        ==================================================== */}

        <section className="mt-8 grid gap-4 sm:grid-cols-2">

          {/* Research areas */}

          <div className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-slate-500">
                  Research Areas
                </p>

                <p className="mt-3 text-3xl font-bold tracking-tight text-slate-900">
                  {researchAreas.length}
                </p>

                <p className="mt-1 text-xs text-slate-400">
                  Areas linked to your profile
                </p>
              </div>

              <div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-indigo-50 text-indigo-600">
                <Microscope className="h-6 w-6" />
              </div>
            </div>
          </div>

          {/* Publications */}

          <div className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-slate-500">
                  Publications
                </p>

                <p className="mt-3 text-3xl font-bold tracking-tight text-slate-900">
                  {publications.length}
                </p>

                <p className="mt-1 text-xs text-slate-400">
                  Publications linked to your profile
                </p>
              </div>

              <div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-violet-50 text-violet-600">
                <FileText className="h-6 w-6" />
              </div>
            </div>
          </div>
        </section>

        {/* ====================================================
            RESEARCH AREAS
        ==================================================== */}

        <section className="mt-8 rounded-3xl border border-slate-200 bg-white p-6 shadow-sm sm:p-8">

          <div className="flex items-center gap-3">
            <div className="flex h-11 w-11 items-center justify-center rounded-xl bg-indigo-50 text-indigo-600">
              <Microscope className="h-5 w-5" />
            </div>

            <div>
              <h2 className="text-lg font-bold text-slate-900">
                Research Areas
              </h2>

              <p className="mt-1 text-xs text-slate-500">
                Your institutional research specializations
              </p>
            </div>
          </div>

          {researchAreas.length > 0 ? (
            <div className="mt-6 flex flex-wrap gap-3">
              {researchAreas.map((area, index) => (
                <span
                  key={`${area}-${index}`}
                  className="rounded-xl border border-indigo-100 bg-indigo-50/70 px-4 py-2.5 text-sm font-medium text-indigo-700"
                >
                  {area}
                </span>
              ))}
            </div>
          ) : (
            <div className="mt-6 rounded-2xl border border-dashed border-slate-200 bg-slate-50 px-5 py-8 text-center">
              <Microscope className="mx-auto h-7 w-7 text-slate-300" />

              <p className="mt-3 text-sm font-medium text-slate-600">
                No research areas available
              </p>

              <p className="mt-1 text-xs text-slate-400">
                Research areas have not been added to your faculty profile.
              </p>
            </div>
          )}
        </section>

        {/* ====================================================
            PUBLICATIONS
        ==================================================== */}

        <section className="mt-8 rounded-3xl border border-slate-200 bg-white p-6 shadow-sm sm:p-8">

          <div className="flex items-center gap-3">
            <div className="flex h-11 w-11 items-center justify-center rounded-xl bg-violet-50 text-violet-600">
              <BookOpen className="h-5 w-5" />
            </div>

            <div>
              <h2 className="text-lg font-bold text-slate-900">
                Research Publications
              </h2>

              <p className="mt-1 text-xs text-slate-500">
                Academic publications associated with your profile
              </p>
            </div>
          </div>

          {publications.length > 0 ? (
            <div className="mt-6 divide-y divide-slate-100">
              {publications.map((publication, index) => (
                <div
                  key={`${publication.title}-${index}`}
                  className="flex flex-col gap-3 py-5 first:pt-0 last:pb-0 sm:flex-row sm:items-start sm:justify-between"
                >
                  <div className="flex min-w-0 gap-3">
                    <div className="mt-0.5 flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-slate-50 text-slate-500">
                      <FileText className="h-4 w-4" />
                    </div>

                    <div className="min-w-0">
                      <h3 className="text-sm font-semibold leading-6 text-slate-900">
                        {publication.title}
                      </h3>

                      <div className="mt-2 flex flex-wrap items-center gap-3 text-xs text-slate-400">
                        {publication.year && (
                          <span className="flex items-center gap-1">
                            <CalendarDays className="h-3.5 w-3.5" />
                            {publication.year}
                          </span>
                        )}

                        {publication.publication_type && (
                          <span>
                            {publication.publication_type}
                          </span>
                        )}

                        {publication.doi && (
                          <span>
                            DOI: {publication.doi}
                          </span>
                        )}
                      </div>
                    </div>
                  </div>

                  {publication.url &&
                    /^https?:\/\//i.test(publication.url) && (
                      <a
                        href={publication.url}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="inline-flex shrink-0 items-center gap-1.5 text-xs font-semibold text-indigo-600 transition hover:text-indigo-800"
                      >
                        View publication
                        <ExternalLink className="h-3.5 w-3.5" />
                      </a>
                    )}
                </div>
              ))}
            </div>
          ) : (
            <div className="mt-6 rounded-2xl border border-dashed border-slate-200 bg-slate-50 px-5 py-8 text-center">
              <BookOpen className="mx-auto h-7 w-7 text-slate-300" />

              <p className="mt-3 text-sm font-medium text-slate-600">
                No publications available
              </p>

              <p className="mt-1 text-xs text-slate-400">
                Publications have not been associated with your faculty profile.
              </p>
            </div>
          )}
        </section>

        {/* ====================================================
            FOOTER
        ==================================================== */}

        <footer className="mt-12 border-t border-slate-200 py-7">
          <div className="flex flex-col items-center justify-between gap-3 text-center sm:flex-row sm:text-left">
            <div>
              <p className="text-xs font-bold tracking-tight text-slate-700">
                RESEARCHPILOT
              </p>

              <p className="mt-1 text-[10px] text-slate-400">
                Faculty Research Portal
              </p>
            </div>

            <p className="text-[10px] font-medium uppercase tracking-[0.15em] text-slate-400">
              RESEARCHPILOT // 2026
            </p>
          </div>
        </footer>
      </div>
    </main>
  );
}
